public CpioArchiveInputStream(InputStream in, int blockSize, String encoding) {
    super(in);
    this.blockSize = blockSize;
    this.encoding = encoding;
}

public CpioArchiveOutputStream(OutputStream out) {
    this(out, CpioConstants.FORMAT_NEW, DEFAULT_ENCODING);
}

public CpioArchiveOutputStream(OutputStream out, short format, int blockSize, String encoding) {
    super(out);
    this.format = format;
    this.blockSize = blockSize;
    this.encoding = encoding;
}

public DumpArchiveInputStream(InputStream in, String encoding) {
    super(in);
    this.entryEncoding = encoding;
}

public TarArchiveInputStream(InputStream in, int blockSize, int recordSize, String encoding) {
    super(in);
    this.blockSize = blockSize;
    this.recordSize = recordSize;
    this.encoding = encoding;
}

public TarArchiveOutputStream(OutputStream out, int blockSize, int recordSize, String encoding) {
    super(out);
    this.blockSize = blockSize;
    this.recordSize = recordSize;
    this.encoding = encoding;
}

public ZipArchiveInputStream(InputStream in, String encoding, boolean allowStoredEntriesWithDataDescriptor, boolean allowStoredEntriesWithCompressionMethodStored) {
    super(in);
    this.encoding = encoding;
    this.allowStoredEntriesWithDataDescriptor = allowStoredEntriesWithDataDescriptor;
    this.allowStoredEntriesWithCompressionMethodStored = allowStoredEntriesWithCompressionMethodStored;
}
